"""CTR generator validation and a pinned pre-CTR default-output regression."""

import hashlib
from pathlib import Path
import subprocess
import sys
import tempfile

LEGACY = 'interface legacy::Wire is legacy { [7] Values(u32 one, u64 two) -> u64 result; }\n'
# Generated by unmodified tools/swipc/swipc.c at 738b4c4, relative name legacy.swipc.
GOLDEN = {
    'h': '5c8a554436d5977eef8d1d5d1f9c5ef4e2bac63833bd6afa7d07e4014fa2bcd9',
    'inc': '8c97d8014c99c79ee5530709b582ebc643242b9fc1332fe77842365d49573716',
}


def main():
    tool = str(Path(sys.argv[1]).resolve())
    with tempfile.TemporaryDirectory(prefix='snx-ctr-swipc-') as directory:
        root = Path(directory)
        out = root / 'output'
        out.mkdir()

        def run(text, *, ctr=True, name='fixture.swipc'):
            (root / name).write_text(text)
            return subprocess.run(
                [tool, *(['--ctr'] if ctr else []), '--root', str(root), '--out', str(out), name],
                text=True,
                capture_output=True,
                timeout=10,
            )

        result = run(LEGACY, ctr=False, name='legacy.swipc')
        assert result.returncode == 0, result.stderr
        for extension, digest in GOLDEN.items():
            assert hashlib.sha256((out / f'legacy.swipc.{extension}').read_bytes()).hexdigest() == digest
        bad = [
            ('[65536] Bad();', 'exceeds 16 bits'),
            ('@stub [1] Bad();', 'does not support @stub'),
            ('@unsorted [1] Bad();', 'does not support @stub'),
            ('[1] Bad(u8 byte);', 'unsupported CTR wire type'),
            ('[1] Bad(i32 value);', 'unsupported CTR wire type'),
            ('[1] Bad(f32 value);', 'unsupported CTR wire type'),
            ('[1] Bad(bool value);', 'unsupported CTR wire type'),
            ('[1] Bad(bytes<3> value);', 'unsupported CTR wire type'),
            ('[1] Bad(u32[2] value);', 'unsupported CTR wire type'),
            ('[1] Bad(buffer<u8, 5> value);', 'unsupported CTR wire type'),
            ('[1] Bad(handle<copy> value);', 'unsupported CTR wire type'),
            ('[1] Bad(aruid value);', 'unsupported CTR wire type'),
            ('[1] Bad() -> pid value;', 'unsupported CTR wire type'),
            ('[1] Bad(pid first, pid second);', 'one CTR pid'),
            ('[1] Bad(u32 value, u64 value);', 'two CTR arguments'),
            ('[1] Bad(bytes<240> data, u64 one, u64 two);', 'exceeds 64 command words'),
            ('[1] Bad() -> (bytes<240> data, u64 one, u32 two);', 'exceeds 64 command words'),
            ('[1] Bad() -> (bytes<240> data, u64 one, handle<copy> object);', 'exceeds 64 command words'),
        ]
        for declaration, diagnostic in bad:
            result = run(f'interface test::Bad {{ {declaration} }}\n')
            assert result.returncode == 1 and diagnostic in result.stderr, (declaration, result.stderr)
            assert not list(out.glob('fixture.swipc.*')), 'Rejected schema published partial outputs'
        result = run('@fallback(stub_ok) interface test::Bad { [1] Bad(); }\n')
        assert result.returncode == 1 and 'does not support @fallback' in result.stderr
        result = run(
            'interface test::Max { [1] Full(bytes<240> data, u32 tail, pid process) -> (bytes<240> data_out, u64 last); }\n'
        )
        assert result.returncode == 0, result.stderr
        generated = (out / 'fixture.swipc.inc').read_text()
        assert 'snx_ctr_ipc_expect(c, 61, 2)' in generated and 'c->out[63]' in generated
        assert 'c->out[64]' not in generated and 'c->in[64]' not in generated
        handles = ', '.join(f'handle<copy> h{i}' for i in range(61))
        result = run(f'interface test::Handles {{ [1] Full() -> ({handles}); }}', name='handles61.swipc')
        assert result.returncode == 0, result.stderr
        grouped = (out / 'handles61.swipc.inc').read_text()
        assert 'c->out[2] = 0xf0000000u;' in grouped and 'snx_ctr_ipc_output_handle(c, 63,' in grouped
        result = run(
            f'interface test::Handles {{ [1] Full() -> ({handles}, handle<copy> excess); }}', name='handles62.swipc'
        )
        assert result.returncode == 1 and 'exceeds 64 command words' in result.stderr
        assert not list(out.glob('handles62.swipc.*'))
        result = subprocess.run(
            [tool, '--root', str(root), '--out', str(out), 'legacy.swipc', '--ctr'],
            text=True,
            capture_output=True,
            timeout=10,
        )
        assert result.returncode == 1 and '--ctr must precede input files' in result.stderr
    print(
        'CTR generator: 20 rejected schemas, grouped-handle/64-word boundaries, mode-order refusal and byte-identical legacy golden passed'
    )


if __name__ == '__main__':
    main()
